  hasil = hasil.filter(
    (b) => b.kategori === q.kategori);

const halaman = Number(q.halaman) || 1;
const per = Number(q.per) || 10;
const awal = (halaman - 1) * per;
res.json({
  data: hasil.slice(awal, awal + per),
  meta: { total: hasil.length, halaman, per }
});

